/* THE STOREFRONT'S PRODUCT + PRICING ENGINE, VERBATIM (Phase 2.7).
   SOURCE is the exact text of Partner 360's familyQty / tierQty / contractPrice / unitPrice,
   its catalog merge through applyMasterPrices, and the colour/MSRP fallbacks, copied from
   homecareproviderservicesordering/public/index.html. The server runs THIS text to price an order,
   so a server price is the shop's price by construction. Never edit here: change the shop and
   re-copy (test/pricing-parity.test.js fails the moment the two differ). */
module.exports = { SOURCE: "function familyQty(p){\n  if(!p.group) return 0;\n  let q=0; for(const {p:cp,qty} of CART.values()){ if(cp.manufacturer===p.manufacturer && cp.group===p.group) q+=qty; }\n  return q;\n}\nfunction tierQty(p, qty){\n  // If the item belongs to a family, tier on the family's combined cart qty; else on this line's qty.\n  const fam=familyQty(p);\n  return Math.max(1, fam>0?fam:(parseInt(qty)||1));\n}\nfunction contractPrice(p){\n  // HCPS-set per-dealer contract price for this exact product (manufacturer slug + code).\n  if(AUTH && AUTH.prices){ const k=(p.manufacturer||\"\")+\"::\"+(p.code||\"\"); if(AUTH.prices[k]!=null) return Number(AUTH.prices[k]); }\n  return null;\n}\nfunction lineRatePrice(p){\n  if(!(AUTH && AUTH.rates)) return null;\n  const r=AUTH.rates[p.manufacturer||\"\"]; if(r==null || r===\"\") return null;\n  const rate=Number(r); if(!isFinite(rate) || rate<=0 || rate>=100) return null;\n  const list=Number(p.dealer_price); if(!isFinite(list) || list<=0) return null;\n  if(Array.isArray(p.tiers) && p.tiers.length) return null;\n  return Math.round(Number((list*(100-rate)).toFixed(6)))/100;\n}\nfunction withUpgrade(p, label){\n  const u=(Array.isArray(p&&p.upgrades)?p.upgrades:[]).find(x=>x&&x.label===label);\n  if(!u) return null;\n  const add=Number(u.price_add), list=Number(p.dealer_price), base=Number(p.base_price);\n  if(!(isFinite(add)&&add>0&&isFinite(list)&&list>0&&isFinite(base)&&base>0)) return null;\n  const r2=v=>Math.round(Number((v*100).toFixed(6)))/100;\n  /* The line's own ratios, read back to 0.01% (they were rounded to the cent): default discount 15.00%,\n     MSRP 1.5000 x list, MAP 0.7000 x MSRP \u2014 so a configured line is exactly what the rule gives its list. */\n  const ratio=(a,b)=>Math.round(a/b*10000)/10000;\n  const d0=Math.round((1-base/list)*10000)/100;\n  const cl=r2(list+add);\n  const q=Object.assign({},p,{_upgrade:String(label),_upgradeAdd:add,_defaultPct:d0,\n    name:String(p.name||p.code)+' \u2014 '+label+' upgrade', dealer_price:cl, base_price:r2(cl*(100-d0)/100)});\n  const msrp=Number(p.msrp), map=Number(p.map);\n  if(isFinite(msrp)&&msrp>0){ q.msrp=r2(cl*ratio(msrp,list)); delete q._msrp_suggested; }\n  if(isFinite(map)&&map>0) q.map=(q.msrp!=null&&isFinite(msrp)&&msrp>0) ? r2(q.msrp*ratio(map,msrp)) : r2(cl*ratio(map,list));\n  return q;\n}\nfunction upgradeAddPurchase(p){\n  const add=Number(p&&p._upgradeAdd); if(!(add>0)) return 0;\n  const r=(AUTH&&AUTH.rates)?Number(AUTH.rates[p.manufacturer||\"\"]):NaN;\n  if(isFinite(r)&&r>0&&r<100) return Math.round(Number((add*(100-r)).toFixed(6)))/100;\n  return Math.round(Number((add*(100-Number(p._defaultPct||0))).toFixed(6)))/100;\n}\nfunction unitPrice(p, qty){\n  // Per-dealer contract price (set by HCPS) wins over list price and quantity tiers.\n  const cp=contractPrice(p);\n  if(cp!=null) return (p&&p._upgrade) ? Math.round(Number(((cp+upgradeAddPurchase(p))*100).toFixed(6)))/100 : cp;\n  // The dealer's own line discount off the standard list (never stacked on a contract price).\n  const lr=lineRatePrice(p);\n  if(lr!=null) return lr;\n  // Quantity-break tiers apply when present.\n  if(Array.isArray(p.tiers)&&p.tiers.length){\n    const q=tierQty(p,qty);\n    /* THRESHOLD-SPECIFIC POOLING (agreed 2026-10-09, Strongback Rev C). A break that names a pool\n       (\"strongback-models\") qualifies on the combined cart quantity of every product of the same line\n       whose breaks name that pool; a break without one qualifies exactly as before (this SKU, or its\n       catalog group). 1\u00d71003AB + 1\u00d7R0001 \u2192 both reach 2+; 4\u00d71003AB + 4\u00d71017 never reach 8+. */\n    const poolQty=name=>{ let n=0, seen=false;\n      for(const {p:cp,qty:cq} of CART.values()){\n        if(cp.manufacturer===p.manufacturer && Array.isArray(cp.tiers) && cp.tiers.some(r=>r&&r.pool===name)){\n          n+=(parseInt(cq)||0); if(cp.code===p.code) seen=true; } }\n      if(!seen) n+=(parseInt(qty)||1);\n      return Math.max(1,n); };\n    let price=null;\n    for(const t of p.tiers){ const mq=(t.minQty??t.min_qty??1); const tq=(t&&t.pool)?poolQty(t.pool):q; if(tq>=mq && t.price!=null) price=Number(t.price); }\n    if(price!=null) return price;\n  }\n  return Number(p.base_price||0);\n}\nfunction linesSubtotal(lines){let t=0;for(const{p,qty}of lines)t+=unitPrice(p,qty)*qty;return t;}\nfunction validFreightTerms(t){\n  const isObj=v=>v!=null&&typeof v==='object'&&!Array.isArray(v);\n  const num=v=>v==null||(typeof v==='number'&&isFinite(v)&&v>=0);\n  const str=v=>v==null||typeof v==='string';\n  const list=a=>Array.isArray(a)&&a.length>0&&a.every(x=>typeof x==='string'&&x.trim()!=='');\n  if(!isObj(t)) return false;\n  if(!str(t.summary)||!str(t.actualNote)||!str(t.otherLabel)) return false;\n  if(t.elseActual!=null&&typeof t.elseActual!=='boolean') return false;\n  if(t.mode==='qty_threshold') return typeof t.freeAtQty==='number'&&isFinite(t.freeAtQty)&&t.freeAtQty>=1&&list(t.qualifyingCodes)&&str(t.label)&&str(t.freeLabel);\n  if(t.mode!=null) return t.mode==='per_item' && num(t.threshold);\n  if(!Array.isArray(t.groups)) return false;\n  for(const g of t.groups){\n    if(!isObj(g)||typeof g.label!=='string'||g.label.trim()==='') return false;\n    if(!(list(g.categories)||list(g.brandKeywords))) return false;\n    if((g.categories!=null&&!list(g.categories))||(g.brandKeywords!=null&&!list(g.brandKeywords))) return false;\n    if(!num(g.freeAt)||!num(g.flatUnder)||!num(g.flatFee)||!num(g.flatBelow)) return false;\n    if(!str(g.freeLabel)||!str(g.flatLabel)) return false;\n  }\n  return t.groups.length>0 || t.elseActual===true;\n}\nfunction freightTermsFor(fileFreight, terms){\n  const file=fileFreight||null;\n  if(terms==null) return {freight:file, source:file?'file':'none', invalid:false};\n  if(!validFreightTerms(terms)) return {freight:file, source:file?'file':'none', invalid:true};\n  const f=JSON.parse(JSON.stringify(terms)); delete f.trace;\n  return {freight:f, source:'record', invalid:false};\n}\nfunction computeFreight(slug,lines){\n  const cfg=mfrInfo(slug).freight; const itemsTotal=linesSubtotal(lines);\n  if(!cfg) return {rows:[],fee:0,itemsTotal,actualNote:\"\"};\n  // per-item shipping: method chosen by order total (e.g. UPS under threshold, LTL over)\n  if(cfg.mode===\"per_item\"){\n    const method = itemsTotal >= (cfg.threshold||1e12) ? \"ltl\" : \"ups\";\n    let fee=0, tbd=false;\n    for(const {p,qty} of lines){\n      const s=p.shipping||{}; let v=s[method];\n      if(v==null) v=(s.ltl!=null?s.ltl:s.ups);          // fall back if selected method n/a\n      if(v===\"tbd\") tbd=true; else if(v!=null && v!==\"included\") fee+=Number(v)*qty;\n    }\n    const label = method===\"ltl\" ? \"LTL freight (order $2,500+)\" : \"UPS/FedEx (order under $2,500)\";\n    /* An item whose delivery charge the manufacturer lists as TBD (Corsicana SBKDB-30) is orderable with its freight\n       PENDING: the actual charge comes from the manufacturer's order confirmation. It is never shown as included,\n       free or $0 (owner, 2026-10-27). */\n    let note = cfg.summary||\"\"; if(tbd) note += \" Freight for some items is pending \u2014 the actual charge comes from the manufacturer's order confirmation.\";\n    return {rows:[Object.assign({label,status:\"peritem\",fee}, tbd?{pending:true}:{})], fee, itemsTotal, actualNote:note};\n  }\n  /* FREE STANDARD SHIPPING BY ORDER QUANTITY (owner, 2026-10-27, AirAvant / BongoRx). An order whose QUALIFYING\n     lines (the part numbers listed in qualifyingCodes \u2014 kits and replenishment units) add up to freeAtQty or more\n     ORDER units ships free, accessories included; below that, every line \u2014 accessory-only orders too \u2014 pays\n     actual shipping (no flat amount is ever quoted). Units are order quantities: a pack of 4 counts once. */\n  if(cfg.mode===\"qty_threshold\"){\n    const codes=(Array.isArray(cfg.qualifyingCodes)?cfg.qualifyingCodes:[]).map(c=>String(c).trim().toUpperCase());\n    const at=Math.max(1,Math.round(Number(cfg.freeAtQty))||1);\n    let n=0; for(const {p,qty} of lines){ if(codes.includes(String(p.code||\"\").trim().toUpperCase())) n+=Math.max(0,parseInt(qty)||0); }\n    const label=cfg.label||\"Standard shipping\";\n    if(n>=at) return {rows:[Object.assign({label,status:\"free\",qualifyingQty:n,freeAtQty:at},cfg.freeLabel?{freeLabel:String(cfg.freeLabel)}:{})], fee:0, itemsTotal, actualNote:\"\"};\n    return {rows:[{label,status:\"actual\",qualifyingQty:n,freeAtQty:at,qtyRemaining:at-n}], fee:0, itemsTotal, actualNote:cfg.actualNote||\"\"};\n  }\n  const assigned=new Set(); const rows=[]; let fee=0; let anyActual=false;\n  for(const g of (cfg.groups||[])){\n    let sub=0;\n    /* A group may select its lines by CATEGORY \u2014 the canonical classification Partner 360 files a\n       product under (agreed 2026-10-09: Strongback accessories pay one $15 shipping & handling per\n       order). A category group never falls back to brand matching. */\n    const cats=(Array.isArray(g.categories)?g.categories:[]).map(c=>String(c).trim().toLowerCase()).filter(Boolean);\n    const kws=Array.isArray(g.brandKeywords)?g.brandKeywords:[];\n    for(const ln of lines){\n      const b=(ln.p.brand||\"\").toLowerCase();\n      const match=cats.length ? cats.includes(String(ln.p.category||\"\").trim().toLowerCase())\n                              : (kws.includes(\"*\")||kws.some(k=>b.includes(k)));\n      if(match&&!assigned.has(ln)){sub+=unitPrice(ln.p,ln.qty)*ln.qty;assigned.add(ln);}\n    }\n    if(sub<=0) continue;\n    // flatFee applies when subtotal < flatBelow (default: whenever below freeAt). Legacy flatUnder = flat fee amount.\n    const flatFee = (g.flatFee!=null?g.flatFee:g.flatUnder);\n    const flatBelow = (g.flatBelow!=null?g.flatBelow:g.freeAt);\n    /* THE MANUFACTURER'S OWN WORDS (agreed 2026-10-10, Bemis). A group may name its terms \u2014\n       freeLabel \"Prepaid freight\", flatLabel \"shipping & handling\" \u2014 and every surface (cart, HCPS\n       email, dealer confirmation) uses them. A group that names none reads exactly as before. */\n    const words=Object.assign({}, g.freeLabel?{freeLabel:String(g.freeLabel)}:{}, g.flatLabel?{flatLabel:String(g.flatLabel)}:{});\n    if(g.freeAt!=null&&sub>=g.freeAt){rows.push(Object.assign({label:g.label,status:\"free\"},words));}\n    else if(flatFee!=null && (flatBelow==null || sub<flatBelow)){\n      fee+=flatFee;\n      rows.push(Object.assign({label:g.label,status:\"flat\",fee:flatFee,\n        waiveRemaining:(flatBelow!=null?flatBelow-sub:0),\n        freeAt:g.freeAt||null, freeRemaining:(g.freeAt!=null?g.freeAt-sub:0)},words));\n    }\n    else {anyActual=true;rows.push({label:g.label,status:\"actual\",freeAt:g.freeAt||null,freeRemaining:(g.freeAt!=null?g.freeAt-sub:0)});}\n  }\n  let other=0; for(const ln of lines){if(!assigned.has(ln))other+=unitPrice(ln.p,ln.qty)*ln.qty;}\n  if(other>0&&cfg.elseActual){anyActual=true;rows.push({label:cfg.otherLabel||\"Other brands\",status:\"actual\"});}\n  return {rows,fee,itemsTotal,actualNote:anyActual?(cfg.actualNote||\"\"):\"\"};\n}\n/* Pure. The same rule as images-api.js normalizeGallery/resolveImage on the admin side \u2014 keep\n   them identical: this SKU's own photo \u2192 the gallery's flagged primary \u2192 (none flagged) the page\n   image, whether or not it is in the gallery \u2192 the gallery's first photo. */\nfunction pageImageFor(pg, sx){\n  const s=v=>String(v==null?'':v).trim();\n  const g=(Array.isArray(pg&&pg.images_gallery)?pg.images_gallery:[]).filter(x=>x&&s(x.url));\n  let i=g.findIndex(x=>x.primary===true);\n  if(i<0) i=g.findIndex(x=>s(x.url)===s(pg&&pg.image));\n  const primary=i>=0?s(g[i].url):(s(pg&&pg.image)||(g.length?s(g[0].url):''));\n  const hero=(sx&&s(sx.image))||primary;\n  const thumbs=g.filter(x=>s(x.url)!==hero).map(x=>({url:s(x.url),caption:x.caption||''}));\n  if(primary && primary!==hero && !thumbs.some(t=>t.url===primary)) thumbs.unshift({url:primary,caption:''});\n  return { hero, thumbs };\n}\n/* A picture that fails to load never ships as a broken image (standing rule): it is replaced\n   by the \"No image\" placeholder, and a broken thumbnail simply leaves the strip. */\nfunction imgFail(el, mode){\n  try{\n    if(mode==='thumb'){ const t=el.closest('.pd-thumb'); if(t) t.remove(); return; }\n    const ph=document.createElement('span'); ph.className='ph'; ph.textContent='No image';\n    el.replaceWith(ph);\n  }catch(e){}\n}\n/* MSRP: THREE STATES, NOT TWO (agreed 2026-10-09).\n     msrp populated                 -> shown as the manufacturer's MSRP\n     msrp empty + msrp_auto not false -> derived (2x dealer price), as every line always has been\n     msrp empty + msrp_auto === false -> NO MSRP. The source has none, and none is invented.\n   The signal is EXPLICIT: a saved edit (override patch) or the master record saying msrp_auto:false.\n   The added-product table's msrp_auto column is NOT read for this \u2014 false is its default, so it\n   cannot tell \"no MSRP on purpose\" from \"nobody set it\" (28 live Ovation rows would lose an MSRP).\n   A layer that says msrp_auto:false with no MSRP of its own clears any MSRP a lower layer carried. */\nfunction noMsrpRule(row, layer){\n  if(!layer || layer.msrp_auto!==false) return row;\n  row.msrp_auto=false;\n  if(layer.msrp==null || layer.msrp===\"\") row.msrp=null;\n  return row;\n}\n/* P0 SECURITY (2026-10-23, issue #2) \u2014 NO WHOLESALE PRICE IS PUBLIC ANY MORE.\n   The static catalog file now carries only what is not commercial; its prices, breaks, MAP, MSRP,\n   price notes (and Access4U's dealer/tier prices, Corsicana's per-item shipping) live in a private\n   table, and the added products (custom_products) and saved edits (product_overrides) are no\n   longer readable with the public key. All three reach the shop ONLY through catalog-layers, which\n   checks the signed-in dealer's entitlement (or the staff preview's ONE dealer) on the server.\n   restoreCatalogFile() is the same text as netlify/functions/_catalog_commercial.js (drift-tested):\n   a commercial key still on a public row is dropped, never trusted; a missing row is a mismatch. */\nconst CATALOG_COMMERCIAL_KEYS=[\"base_price\",\"tiers\",\"dealer_price\",\"tier_prices\",\"msrp\",\"map\",\"price_note\",\"unit_cost\",\"shipping\",\"upgrades\"];\n/* ROW IDENTITY (P0 review, 2026-10-23). A commercial row is attached to a public row ONLY when the\n   public row is exactly the row it was made for: every commercial entry carries `h`, the SHA-256 of\n   its public row's non-commercial fields (canonical JSON, keys sorted), and the whole line carries\n   its identity \u2014 the SHA-256 of those fingerprints in file order. A reordered duplicate part number,\n   a changed name / family / group / image with the same part numbers and row count, a public file\n   newer or older than the commercial record, or an entry with no fingerprint: refused, never matched\n   by position. Pure JS (sync, no crypto API) so the browser, the server engine copy and the tools\n   compute the same value. */\nfunction catalogSha256(str){\n  const K=[0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,\n    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,\n    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,\n    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];\n  const m=new TextEncoder().encode(String(str)), l=m.length, n=((l+9+63)>>6)<<6, b=new Uint8Array(n);\n  b.set(m); b[l]=0x80;\n  const dv=new DataView(b.buffer); dv.setUint32(n-8,Math.floor(l/0x20000000)); dv.setUint32(n-4,(l*8)>>>0);\n  const H=[0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19], w=new Array(64);\n  for(let o=0;o<n;o+=64){\n    for(let i=0;i<16;i++) w[i]=dv.getUint32(o+i*4);\n    for(let i=16;i<64;i++){ const x=w[i-15], y=w[i-2];\n      w[i]=(w[i-16]+(((x>>>7)|(x<<25))^((x>>>18)|(x<<14))^(x>>>3))+w[i-7]+(((y>>>17)|(y<<15))^((y>>>19)|(y<<13))^(y>>>10)))|0; }\n    let a=H[0],c1=H[1],c2=H[2],d=H[3],e=H[4],f=H[5],g=H[6],h=H[7];\n    for(let i=0;i<64;i++){\n      const t1=(h+(((e>>>6)|(e<<26))^((e>>>11)|(e<<21))^((e>>>25)|(e<<7)))+((e&f)^(~e&g))+K[i]+w[i])|0;\n      const t2=((((a>>>2)|(a<<30))^((a>>>13)|(a<<19))^((a>>>22)|(a<<10)))+((a&c1)^(a&c2)^(c1&c2)))|0;\n      h=g; g=f; f=e; e=(d+t1)|0; d=c2; c2=c1; c1=a; a=(t1+t2)|0;\n    }\n    H[0]=(H[0]+a)|0; H[1]=(H[1]+c1)|0; H[2]=(H[2]+c2)|0; H[3]=(H[3]+d)|0; H[4]=(H[4]+e)|0; H[5]=(H[5]+f)|0; H[6]=(H[6]+g)|0; H[7]=(H[7]+h)|0;\n  }\n  return H.map(x=>('00000000'+(x>>>0).toString(16)).slice(-8)).join('');\n}\nfunction catalogCanon(v){\n  if(Array.isArray(v)) return '['+v.map(catalogCanon).join(',')+']';\n  if(v && typeof v==='object') return '{'+Object.keys(v).sort().map(k=>JSON.stringify(k)+':'+catalogCanon(v[k])).join(',')+'}';\n  return JSON.stringify(v===undefined?null:v);\n}\n/* A row's identity fingerprint: its non-commercial fields only (the public half \u2014 the same value\n   whether the row still carries prices or not). */\nfunction catalogRowPrint(r){\n  const p={};\n  if(r && typeof r==='object' && !Array.isArray(r)) Object.keys(r).forEach(k=>{ if(CATALOG_COMMERCIAL_KEYS.indexOf(k)<0) p[k]=r[k]; });\n  return catalogSha256(catalogCanon(p));\n}\n/* A catalog file's identity (its version): the fingerprints of its rows, in file order. */\nfunction catalogIdentity(rows){\n  return catalogSha256((Array.isArray(rows)?rows:[]).map(catalogRowPrint).join('\\n'));\n}\n/* Key order inside nested commercial objects (2026-10-25). A record read back from Postgres jsonb keeps\n   every value but reorders the keys of nested objects (a tier {minQty, price} comes back {price, minQty};\n   Corsicana's shipping {white_glove, ups, ltl} comes back {ltl, ups, white_glove}). Values are unchanged, but\n   anything that compares text \u2014 the Gold Standard fingerprint \u2014 would see a change no dealer can. Every\n   priced catalog file uses one key order per nested object (verified on 4b1bad3: tiers always minQty, price;\n   shipping always white_glove, ups, ltl), so restore puts those keys back in that order, then any other key in\n   its stored order. Only key order changes, never a value; a restore from an in-memory overlay is unchanged. */\nconst NESTED_KEY_ORDER=['minQty','min_qty','price','pool','white_glove','ups','ltl'];\nfunction nestedOrder(v){\n  if(Array.isArray(v)) return v.map(nestedOrder);\n  if(!v || typeof v!=='object') return v;\n  const out={};\n  NESTED_KEY_ORDER.forEach(k=>{ if(Object.prototype.hasOwnProperty.call(v,k)) out[k]=nestedOrder(v[k]); });\n  Object.keys(v).forEach(k=>{ if(!Object.prototype.hasOwnProperty.call(out,k)) out[k]=nestedOrder(v[k]); });\n  return out;\n}\n\nfunction restoreCatalogFile(rows, overlay){\n  if(!Array.isArray(rows)) throw new Error('catalog_file_mismatch: the public catalog file is not a list');\n  if(!Array.isArray(overlay) || overlay.length!==rows.length)\n    throw new Error('catalog_file_mismatch: '+rows.length+' public row(s), '+(Array.isArray(overlay)?overlay.length:'no')+' commercial row(s)');\n  const by={};\n  overlay.forEach(o=>{ if(o && o.k!=null) by[String(o.k)]=o; });\n  if(Object.keys(by).length!==overlay.length) throw new Error('catalog_file_mismatch: the commercial rows are not one per catalog row');\n  const seen={};\n  return rows.map(r=>{\n    const c=String(r&&r.code!=null?r.code:''); const n=seen[c]=(seen[c]||0)+1; const k=c+'#'+(n-1);\n    const o=by[k];\n    if(!o) throw new Error('catalog_file_mismatch: no commercial row for '+k);\n    if(typeof o.h!=='string' || !/^[0-9a-f]{64}$/.test(o.h)) throw new Error('catalog_file_mismatch: the commercial row for '+k+' has no identity fingerprint');\n    if(catalogRowPrint(r)!==o.h) throw new Error('catalog_file_mismatch: '+k+' is not the catalog row its commercial row was made for');\n    const f=(o.f && typeof o.f==='object') ? o.f : {};\n    const out={};\n    (Array.isArray(o.order)?o.order:[]).forEach(key=>{\n      if(CATALOG_COMMERCIAL_KEYS.indexOf(key)>=0){ if(key in f) out[key]=nestedOrder(f[key]); }\n      else if(r && key in r) out[key]=r[key];\n    });\n    Object.keys(r||{}).forEach(key=>{ if(!(key in out) && CATALOG_COMMERCIAL_KEYS.indexOf(key)<0) out[key]=r[key]; });\n    Object.keys(f).forEach(key=>{ if(!(key in out) && CATALOG_COMMERCIAL_KEYS.indexOf(key)>=0) out[key]=nestedOrder(f[key]); });\n    return out;\n  });\n}\n/* The line's commercial layers, for the signed-in dealer or the staff preview \u2014 nobody else.\n   Asks for the version that belongs to THIS public file (its identity) and refuses an answer for any\n   other. Throws on anything but a complete answer: the caller fails closed. */\nasync function commercialLayers(slug, rows){\n  const identity = catalogIdentity(rows||[]);\n  const jwt = (typeof AUTH !== 'undefined' && AUTH && AUTH.session && AUTH.session.access_token) || '';\n  const pvt = (typeof PREVIEW !== 'undefined' && PREVIEW && PREVIEW.token) ? PREVIEW.token : '';\n  if(!jwt && !pvt) throw new Error('no dealer session or preview to authorise pricing');\n  const hdr = jwt ? { authorization: 'Bearer ' + jwt } : { 'x-hcps-preview': pvt };\n  const r = await fetch('/.netlify/functions/catalog-layers?manufacturer=' + encodeURIComponent(slug) + '&identity=' + identity, { headers: hdr, cache: 'no-store' });\n  if(!r.ok) throw new Error('catalog-layers returned HTTP ' + r.status);\n  const j = await r.json();\n  if(!j || j.ok!==true || !Array.isArray(j.file_overlay) || !Array.isArray(j.custom_products) || !Array.isArray(j.product_overrides))\n    throw new Error('catalog-layers answered without its layers');\n  if(j.identity_sha256!==identity) throw new Error('catalog-layers answered for another version of the catalog file');\n  return j;\n}\nasync function mergeCatalogEdits(slug, prods){\n  /* FAILS CLOSED. Without the line's commercial layers nothing is listed: a product the saved\n     edits had hidden would otherwise reappear, and there is no public price left to show. */\n  let layers;\n  try{ layers=await commercialLayers(slug, prods||[]); prods=restoreCatalogFile(prods||[], layers.file_overlay); }\n  catch(err){\n    CATALOG_SOURCE[slug]={ source:'unavailable', reason:'pricing unavailable: '+((err&&err.message)||err), products:0, at:new Date().toISOString() };\n    try{ console.warn('[HCPS] '+slug+': pricing unavailable \u2014 '+((err&&err.message)||err)); }catch(e){}\n    return [];\n  }\n  const H={apikey:CONFIG.SUPABASE_ANON,authorization:'Bearer '+CONFIG.SUPABASE_ANON};\n  try{\n    /* product_images is LEGACY (Phase 2.4): its rows were migrated into the one image\n       authority \u2014 the product page's gallery, a SKU's own photo, or the catalog override \u2014\n       and the storefront no longer reads it (the table is kept, read-only, for one release).\n       One precedence, in one place: pageImageFor() below. */\n    const [cust,links,overs,media] = await Promise.all([\n      Promise.resolve(layers.custom_products),\n      fetch(`${CONFIG.SUPABASE_URL}/rest/v1/product_links?manufacturer=eq.${encodeURIComponent(slug)}&select=code,label,url`,{headers:H}).then(x=>x.ok?x.json():[]),\n      Promise.resolve(layers.product_overrides),\n      fetch(`${CONFIG.SUPABASE_URL}/rest/v1/product_media?manufacturer=eq.${encodeURIComponent(slug)}&select=code,kind,url,title,sort&order=sort`,{headers:H}).then(x=>x.ok?x.json():[]),\n    ]);\n    const om=Object.fromEntries((overs||[]).map(o=>[o.code,o.patch||{}]));\n    /* PRICE INDEX \u2014 built BEFORE anything is hidden, because the base part number a colour\n       variant inherits from is very often the retired one. 10002 is hidden and priced;\n       10002BLUE is what a dealer buys. Losing the hidden row would lose the fallback. */\n    /* THE LADDER TRAVELS WITH THE PRICE, FROM THE SAME ROW.\n       The index used to carry the base price alone, which is how sixty Gen 2 boots came to\n       show the right price on the card and then charge it at every quantity \u2014 10002BLUE had a\n       ladder typed in by hand, BLACK/GREY/RED had none, and unitPrice() falls straight through\n       to base_price when p.tiers is empty. A dealer ordering 21 black paid the single-unit price each where\n       21 blue cost the 21+ price.\n       Both facts are recorded together and only from the row that actually supplied the price.\n       Taking the price from one layer and the ladder from another would build a schedule that\n       never existed on anyone's price list. */\n    const priceIndex={}, tierIndex={};\n    const noteP=(code,v,tiers)=>{ if(v==null||v==='') return; const num=Number(v);\n      if(isFinite(num)&&num>0){ const k=String(code).toUpperCase();\n        if(priceIndex[k]==null){\n          priceIndex[k]=num;\n          tierIndex[k]=(Array.isArray(tiers)&&tiers.length)?tiers:null;\n        } } };\n    (overs||[]).forEach(o=>noteP(o.code,(o.patch||{}).base_price,(o.patch||{}).tiers));\n    (cust ||[]).forEach(c=>noteP(c.code,c.base_price,c.tiers));\n    prods.forEach(x=>noteP(x.code,x.base_price,x.tiers));\n    /* `group` is now overridable. It decides whether several SKUs collapse into one product\n       card with a size picker or appear as separate cards, and it used to exist only in the\n       deployed catalog file \u2014 so a wrong grouping could not be corrected without a redeploy.\n       An admin edit now takes effect here immediately, like every other catalog edit. */\n    /* \"map\" belongs here for the same reason every other price field does: a MAP that can only\n   be fixed by redeploying the catalog file is a MAP that stays wrong. */\n    const OV_KEYS=[\"name\",\"category\",\"subcategory\",\"description\",\"price_note\",\"base_price\",\"msrp\",\"map\",\"tiers\",\"image\",\"group\"];\n    prods=prods.map(p=>{ const pa=om[p.code]; if(!pa) return p; const merged={...p};\n      for(const k of OV_KEYS) if(k in pa && pa[k]!=null) merged[k]=pa[k];\n      noMsrpRule(merged, pa);\n      /* A name typed in the admin is a deliberate decision and outranks the enrichment\n         record below; without this flag the enrichment layer would silently undo it. */\n      if(pa.name!=null && pa.name!==\"\") merged._nameFromOverride=true;\n      if(pa.category!=null && pa.category!==\"\") merged._catFromOverride=true;\n      if(pa.active===false) merged._hidden=true; return merged; }).filter(p=>!p._hidden);\n    const have=new Set(prods.map(p=>p.code));\n    /* An ADDED product had no way to carry a group at all, so every one of them rendered as\n       its own card even when it was plainly a size of something already on the shelf. Added\n       products now read the same override layer, which is where their group can be set. */\n    (cust||[]).forEach(c=>{ if(c.active===false||have.has(c.code)) return;\n      const pa=om[c.code]||{};\n      if(pa.active===false) return;\n      /* map was SELECTED above but never copied onto the row, so an added product's MAP\n         reached the browser and was thrown away \u2014 the one layer where MAP is most often the\n         only place it is recorded. Every other price field was carried; this one was missed. */\n      /* An ADDED product carries its line, like every catalog-file row does. It did not, so\n         added products (on Ovation that is 87, including every black, grey and red Gen 2 boot)\n         reached the cart with no manufacturer: the order grouped them under no line, their\n         contract prices (\"slug::code\") never matched, their quantity breaks pooled with any\n         other unlined item, and a saved cart silently dropped them on the next sign-in. */\n      const row={manufacturer:slug,code:c.code,name:c.name,category:c.category||\"\",base_price:c.base_price,msrp:c.msrp,\n        map:(c.map==null||c.map===\"\")?null:c.map,\n        image:c.image||\"\",description:c.description||\"\",tiers:c.tiers||null,price_note:c.price_note||\"\",_custom:true};\n      for(const k of OV_KEYS) if(k in pa && pa[k]!=null) row[k]=pa[k];\n      noMsrpRule(row, pa);\n      prods.push(row); });\n    const lm=Object.fromEntries((links||[]).map(l=>[l.code,l]));\n    prods.forEach(p=>{ const L=lm[p.code]; if(L&&L.url){ p.moreUrl=L.url; p.moreLabel=L.label||\"More Information\"; } });\n    // media gallery (extra images, videos, brochures, links) keyed by code\n    const mm={}; (media||[]).forEach(m=>{ if(m&&m.code&&m.url){ (mm[m.code]=mm[m.code]||[]).push(m); } });\n    prods.forEach(p=>{ if(mm[p.code]) p.media=mm[p.code]; p._priceIndex=priceIndex; p._tierIndex=tierIndex; });\n  }catch(e){}\n  // ---- product-content enrichment layer (LIVE gate) ----\n  // Source of truth is Supabase product_content. \"Live on Partner 360\" is the PUBLISHED state:\n  // the enrichment tool's Approve = internal sign-off (not shown), Publish = live. So the shop\n  // loads status IN (published, active) \u2014 NOT 'approved', which is the internal review state.\n  // Falls back to the static ./data/content file, respecting the same gate.\n  const LIVE_STATUSES=['published','active'];\n  /* VISIBLE \u2260 SELLABLE (agreed 2026-10-08). A DISCONTINUED page stays on Partner 360 for\n     reference \u2014 its description, documents and a pointer to the current product \u2014 but nothing\n     on it can be ordered. hidden (or switched off) is the way to remove a page entirely. Server\n     pricing runs this same code, so an order for a discontinued product is refused there too. */\n  const VISIBLE_STATUSES=['published','active','discontinued'];\n  let _gated=0;                 // declared here because it is read after the catch below\n  try{\n    let pages=null;\n    /* the preview's own enrichment (static content file) comes first on a staging deploy */\n    if(typeof STAGING!==\"undefined\"&&STAGING){ try{ const cr=await fetch(`./data/content/${slug}.json`,{cache:\"no-store\"}); if(cr.ok){ const cj=await cr.json(); RAW.content[slug]=cj; const pg=(cj&&cj.pages)||{};\n      const keys=Object.keys(pg).filter(k=>pg[k].disabled!==true&&VISIBLE_STATUSES.includes(pg[k].status)); if(keys.length){ pages={}; keys.forEach(k=>{ pages[k]=pg[k]; }); } } }catch(e){} }\n    if(!pages) try{\n      const PC_URL=`${CONFIG.SUPABASE_URL}/rest/v1/product_content?manufacturer=eq.${encodeURIComponent(slug)}&status=in.(${VISIBLE_STATUSES.join(',')})&select=page_key,status,skus,name,tagline,description,features,clinical_applications,options,billing_codes,specs,warranty,source_url,image,images_gallery,sizing_table,sizing_note,documents,videos,variant_group,parent_key,variant_label,subcategory`;\n      /* card_image (2026-10-12): the catalog-card photo the President chose for a grouped page. Until the\n         database has the column, the pages are read without it \u2014 exactly as before. */\n      let rows=await fetch(PC_URL+',card_image',{headers:H}).then(x=>x.ok?x.json():null);\n      if(rows==null) rows=await fetch(PC_URL,{headers:H}).then(x=>x.ok?x.json():null);\n      if(Array.isArray(rows)&&rows.length){ pages={}; rows.forEach(r=>{ pages[r.page_key]=r; }); }\n    }catch(e){}\n    if(!pages){ // static fallback (same live gate applied client-side)\n      const cr=await fetch(`./data/content/${slug}.json`,{cache:\"no-store\"});\n      if(cr.ok){ const cj=await cr.json(); const pg=(cj&&cj.pages)||{}; pages={};\n        for(const k in pg){ const st=pg[k].status; if(pg[k].disabled===true) continue; if(!CONFIG.CONTENT_APPROVED_ONLY || VISIBLE_STATUSES.includes(st)) pages[k]=pg[k]; } }\n    }\n    if(pages){\n      // Variant-aware routing: a product family (e.g. Gen 2 Walking Boot) can resolve into\n      // multiple MODEL variants, each with its own page/images. A SKU is routed to its model\n      // by the catalog `group` string. Falls back to the image-basename key (single-model\n      // products, or a model variant not yet approved \u2192 shows the parent/base content).\n      // variant_group may hold ONE catalog group or a pipe-delimited list (e.g. a product that\n      // spans \"standard\" + \"(4XL)\" groups). Register every listed group \u2192 this page_key.\n      const variantByGroup={}; Object.keys(pages).forEach(k=>{ const vg=pages[k]&&pages[k].variant_group; if(!vg) return; String(vg).split('|').forEach(g=>{ g=g.trim(); if(g) variantByGroup[g]=k; }); });\n      // SKU index \u2014 the durable join. Both sides carry the same part number, so a content page\n      // that lists a SKU owns the catalog product with that code, whatever its page_key or image\n      // filename happens to be. This is what stops an enriched page from silently not rendering\n      // because its slug didn't match an image basename.\n      const pageBySku={}, skuEntry={}, skuOff={}, skuDisc={};\n      Object.keys(pages).forEach(k=>{ const arr=pages[k]&&pages[k].skus;\n        if(!Array.isArray(arr)) return;\n        arr.forEach(sx=>{ const c=String((sx&&(sx.sku||sx.code))||'').trim().toUpperCase();\n          if(!c) return;\n          /* \"OFF\" HIDES A SKU (Phase 2.5). A SKU switched off, or marked hidden, on the page that\n             owns it is not shown. A SKU marked DISCONTINUED stays visible for reference and\n             cannot be ordered (visible \u2260 sellable). */\n          if(!pageBySku[c] && sx && (sx.disabled===true || String(sx.status||'')==='hidden')) skuOff[c]=true;\n          if(!pageBySku[c] && sx && String(sx.status||'')==='discontinued') skuDisc[c]=true;\n          if(!pageBySku[c]) pageBySku[c]=k;\n          if(!skuEntry[c]) skuEntry[c]=sx; }); });\n      /* Does this line list only what has been enriched? Read from the manufacturer record\n         loaded at boot, so it is a data setting and not a code change per line. */\n      const _mfr=(state.manufacturers||[]).find(m=>m.slug===slug);\n      const enrichedOnly=!!(_mfr&&_mfr.enrichedOnly);\n      const catMap=(_mfr&&_mfr.categoryMap)||null;\n      /* IDENTITY IS DECLARED, NOT GUESSED.\n         A SKU belonged to an enrichment page by SKU list, then variant group, then \u2014 if both\n         missed \u2014 by IMAGE FILENAME. That last one is how \"Ovation Pressure Relief Pad\" came to\n         own 733-002-PRPSHOE: the page lists 733-002PRP, an entirely different part number, and\n         the two merely shared a photo. Editing the page then appeared to do nothing, because\n         the product it was steering was never the product on screen.\n\n         A page now owns a SKU only where someone SAID so \u2014 its SKU list, or a variant group,\n         both of which are curated fields. A SKU no page claims is left unlinked and reported,\n         instead of being quietly attached to whichever page happens to reuse its photograph. */\n      prods=prods.filter(p=>!skuOff[String(p.code||'').trim().toUpperCase()]);\n      prods.forEach(p=>{\n        const sKey=pageBySku[String(p.code||'').trim().toUpperCase()];\n        const vKey=p.group&&variantByGroup[p.group];\n        const key=(sKey&&pages[sKey])?sKey:((vKey&&pages[vKey])?vKey:null);\n        if(!key) p._unlinked=true;\n        const pg=key&&pages[key];\n        if(pg && (pg.status==='discontinued' || skuDisc[String(p.code||'').trim().toUpperCase()])) p._discontinued=true;\n        if(pg){\n          /* THE APPROVED NAMES. Enrichment is where these products are actually named, and\n             none of it reached the shop: a card was titled from the catalog `group` string and\n             each option from the raw catalog name, so the reviewed names were never seen by a\n             dealer. Both levels now come from the enrichment record when it has one \u2014\n             the per-SKU name for the option, the page name for the card \u2014 while a name typed\n             in the admin still wins over both. */\n          /* THE PRODUCT DEFINITION. An enrichment page IS a product: it is where someone\n             decided which SKUs belong together, what the product is called and what it says.\n             Recording the page a SKU resolved to lets the shop bundle exactly as designed,\n             instead of inferring product boundaries from the catalog `group` string \u2014 a\n             legacy key that splits one product across several cards and occasionally puts\n             two different products on one. */\n          p._pageKey=key;\n          const _sx=skuEntry[String(p.code||'').trim().toUpperCase()];\n          const _sxName=_sx && String(_sx.name||'').trim();\n          if(_sxName && !p._nameFromOverride) p.name=_sxName;\n          /* THE OPTION TEXT IS AUTHORED, NOT DERIVED. Enrichment holds a per-SKU option\n             field (\"X-Small Blue\") next to the per-SKU name (\"... - X-Small\"), and only the\n             name reached the shop \u2014 so four colours of one size all rendered as the same\n             \"X-Small\" and a dealer had no way to tell them apart, or to know the colour they\n             had just added to the cart. The authored option now travels with the product and\n             is what every dealer-facing surface renders. */\n          const _sxOpt=_sx && String((_sx.size!=null?_sx.size:(_sx.option!=null?_sx.option:''))||'').trim();\n          if(_sxOpt) p._skuOption=_sxOpt;\n          /* PARENT FAMILIES (owner, 2026-10-31, Access4U). A family page may name each SKU's choices as axes \u2014\n             {Length:\"4 ft (48\\\")\", Width:\"36\\\" wide\"} \u2014 and its own specification rows. The pickers then offer one\n             control per axis, and each combination is exactly one SKU from the price list. */\n          if(_sx && _sx.axes && typeof _sx.axes==='object' && !Array.isArray(_sx.axes) && Object.keys(_sx.axes).length) p._axes=Object.assign({},_sx.axes);\n          if(p._axes){ const _ix=(pg.skus||[]).indexOf(_sx); if(_ix>=0) p._axisOrder=_ix; }\n          if(_sx && Array.isArray(_sx.specs) && _sx.specs.length) p._skuSpecs=_sx.specs.filter(r=>r&&r.label&&r.value!=null&&r.value!=='');\n          if(pg.name) p._encPage=String(pg.name).trim();\n          /* THE ENRICHMENT DESCRIPTION IS THE DESCRIPTION (Phase 2.5). It used to fill only a\n             blank, so wherever the catalog file carried its own text the approved description\n             never reached a dealer. Content belongs to enrichment; the catalog text is a\n             fallback for a SKU no page describes. */\n          if(pg.description) p.description=pg.description;\n          if(pg.tagline) p._tagline=pg.tagline;\n          /* The subcategory (\"Thumb Spicas\", \"Wrist Braces\") is the specific thing a dealer\n             actually shops for. It is recorded during enrichment and was already shown on the\n             card, but it was never SELECTED from product_content, so every product arrived\n             without one and the category filter had nothing finer than the broad clinical\n             category to offer. Category itself is deliberately left alone \u2014 that belongs to\n             the catalog and its override layer, and enrichment must not quietly move a\n             product out of the category someone put it in. */\n          /* THE ENRICHMENT RECORD IS THE MASTER, so its subcategory wins outright. It used to\n             defer to whatever the catalog layer already held, which meant a subcategory changed\n             in the Structure Map could be silently ignored by the shop \u2014 the exact failure the\n             master-record rule exists to prevent. */\n          if(pg.subcategory) p.subcategory=pg.subcategory;\n          /* DERIVE the category from the subcategory. This is what makes one edit enough: change\n             a product's subcategory in enrichment and it moves to the right part of the shop,\n             with nothing else to update. A category typed directly in the admin still wins \u2014 the\n             map fills the answer, it does not overrule a decision. */\n          if(catMap && p.subcategory && !p._catFromOverride){\n            const mapped=catMap[p.subcategory];\n            if(mapped) p.category=mapped;\n          }\n          const F=pg.features, C=pg.clinical_applications, O=pg.options, B=pg.billing_codes;\n          if(Array.isArray(F)&&F.length) p._features=F;\n          if(Array.isArray(C)&&C.length) p._clinical=C;\n          if(O&&typeof O==='object'&&Object.keys(O).length) p._options=O;\n          if(Array.isArray(B)&&B.length) p._billing=B;\n          /* THE ONE IMAGE RULE (Phase 2.4): this SKU's own photo \u2192 the page's primary photo\n             (none flagged: the page image, then the gallery's first photo) \u2192 the catalog layer\n             already on p. The rest of the gallery becomes thumbnails. */\n          /* THE CATALOG-CARD PHOTO IS CHOSEN, NOT INFERRED (2026-10-12). A grouped page's card used the\n             first option that had a photo \u2014 so the order of the catalog file decided what every dealer saw\n             before choosing a shape or size. The President now chooses it (an option's photo, another\n             approved photo, or \"none\" for no photo); groupLeads() puts it on the card. Presentation only:\n             no option, price, order or grouping changes. */\n          if(pg.card_image) p._cardImage=String(pg.card_image).trim();\n          /* \"none\": this option has no exact photo of its own (owner rule, 2026-10-31) \u2014 no hero is borrowed from another\n             option or the family; the detail page says \"Image not available for this option\" and shows no other picture.\n             Handled here, beside pageImageFor, so that shared function stays exactly as the frozen lines render it. */\n          if(_sx && String(_sx.image==null?'':_sx.image).trim()==='none'){ p.image=''; p._noOptionImage=true; if(Array.isArray(p.media)) p.media=p.media.filter(m=>m&&m.kind!=='image'); }\n          else { const pi=pageImageFor(pg,_sx);\n            if(pi.hero) p.image=pi.hero;\n            if(pi.thumbs.length){ p.media=Array.isArray(p.media)?p.media:[];\n              pi.thumbs.forEach(t=>{ if(!p.media.some(m=>m.url===t.url)) p.media.push({kind:'image',url:t.url,title:t.caption||''}); }); } }\n          if(Array.isArray(pg.specs)&&pg.specs.length) p._specs=pg.specs.filter(s=>s&&(s.label||s.value));\n          // sizing_table is saved as {columns:[],rows:[]} by the enrichment tool; legacy rows may be\n          // a bare array. Accept BOTH \u2014 testing only for an array silently hid every sizing chart.\n          var _st=pg.sizing_table, _stRows=Array.isArray(_st)?_st:((_st&&Array.isArray(_st.rows))?_st.rows:[]);\n          if(_stRows.length){ p._sizing=_stRows;\n            if(_st&&Array.isArray(_st.columns)&&_st.columns.length) p._sizingCols=_st.columns; }\n          /* A sizing note is content in its own right (\"Measure the calf at its widest point\")\n             and used to be dropped whenever there was no table to hang it under. */\n          if(pg.sizing_note) p._sizingNote=pg.sizing_note;\n          if(pg.warranty) p._warranty=pg.warranty;\n          if(pg.source_url) p._sourceUrl=pg.source_url;\n          if(Array.isArray(pg.documents)&&pg.documents.length) p._documents=pg.documents;\n          if(Array.isArray(pg.videos)&&pg.videos.length) p._videos=pg.videos;\n        }});\n      /* THE LISTING GATE. Applied only after every page has had its chance to claim a SKU \u2014\n         by SKU, by variant group, and by image key \u2014 so nothing is dropped merely because it\n         was matched late. A SKU no page claims is not a finished product on this line, so it\n         is not offered to dealers. It stays priced and intact in the Product Catalog and\n         reappears the moment a page lists it. */\n      if(enrichedOnly){\n        const before=prods.length;\n        prods=prods.filter(p=>p._pageKey && pages[p._pageKey]);\n        _gated=before-prods.length;\n      }\n    }\n  }catch(e){}\n  if(_gated) try{ console.log('[HCPS] '+slug+': '+_gated+' SKU(s) not listed \u2014 no enrichment page'); }catch(e){}\n  return await applyMasterPrices(slug, prods.map(inheritColorPrice).map(fillMsrp));\n}\n\n/* \u2550\u2550\u2550 PHASE 5 \u2014 COMMERCIAL FIELDS FROM THE MASTER RECORD \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n   Dealer price, MSRP, MAP and quantity breaks have a single home now:\n   product_skus, reached through the catalog-feed function. Everything else on\n   a product \u2014 its name, category, image, grouping, description \u2014 still comes\n   from where it has always come from, and this pass cannot touch any of it.\n\n   WHY THE LAYERS STILL WIN A DISAGREEMENT\n   The admin writes prices to custom_products and product_overrides. It does\n   NOT yet write to product_skus; that record is rebuilt from the layers when\n   the reconciler runs. So between reconciles the layers are the NEWER truth,\n   and a difference here almost always means somebody changed a price this\n   morning and the record has not caught up \u2014 not that the record is right and\n   the storefront is wrong.\n\n   Handing the record authority before the writes move would therefore quote a\n   dealer this month's price one day and last month's the next, depending on\n   when the reconciler last ran. So in Phase 5 the feed is read, compared, and\n   reported \u2014 and where the two disagree the layers stand. Authority transfers\n   in Phase 6, in the same change that moves the writes, by flipping the one\n   constant below. That ordering is the entire safety property; the flag is\n   deliberately not a setting anybody should turn on casually.\n\n   Nothing here can empty a catalog. Every failure \u2014 no session, feed down, a\n   line not yet migrated, a migrated line that answers with nothing \u2014 leaves\n   the products exactly as the layers built them, and says why in\n   window.CATALOG_SOURCE. */\n/* PHASE 6 ARRIVED PER LINE, NOT ALL AT ONCE.\n   This was one constant because there was one decision to make. There isn't:\n   Bemis has nine SKUs whose every number is visible on one screen, PediFix has\n   497 that have not been migrated at all, and the honest state of the system is\n   that those two lines are in different phases. So authority is now the feed's\n   answer, per manufacturer, read from the record's own metadata \u2014 and this\n   constant becomes what it should always have been, a single switch that takes\n   every line back to the layers without a database change or a deploy of the\n   admin. Set it false and nothing below can transfer authority to anything. */\nconst MASTER_PRICES_ENABLED = true;\nconst CATALOG_SOURCE = {};\ntry{ window.CATALOG_SOURCE = CATALOG_SOURCE; }catch(e){}\n\n/* The comparison itself: pure, so it can be tested against fixtures.\n   Mutates `prods` only when the record is authoritative; otherwise it looks\n   and reports and changes nothing. */\nfunction reconcileShopPrices(prods, rows, authoritative){\n  const norm = c => String(c == null ? \"\" : c).toUpperCase().replace(/[^A-Z0-9]/g, \"\");\n  const near = (a, b) => (a == null && b == null) ? true\n                       : (a == null || b == null) ? false\n                       : Math.abs(Number(a) - Number(b)) < 0.005;\n  const ladder = t => Array.isArray(t)\n    ? t.map(x => Math.round(Number(x.min_qty != null ? x.min_qty : x.minQty)) + ':' + Number(x.price) + (x.pool ? '@' + x.pool : ''))\n       .sort().join(',')\n    : '';\n\n  const by = {};\n  (rows || []).forEach(r => { by[norm(r.code)] = r; });\n\n  let matched = 0, unmatched = 0;\n  const diffs = [];\n  (prods || []).forEach(p => {\n    const m = by[norm(p.code)];\n    if(!m){ unmatched++; return; }\n    matched++;\n    [\"base_price\", \"msrp\", \"map\"].forEach(k => {\n      /* A field the record does not carry is never used to blank one the\n         storefront has. \"The record says nothing\" is not \"the price is gone\". */\n      if(m[k] == null) return;\n      if(!near(p[k], m[k])){\n        diffs.push({ code: p.code, field: k, layers: p[k], record: m[k] });\n        if(authoritative) p[k] = m[k];\n      }\n    });\n    /* The record says this SKU has NO MSRP (msrp empty, msrp_auto false). The storefront may\n       already have derived or inherited one; that is a difference, and on an authoritative line\n       the record's \"none\" wins. */\n    /* The unit a dealer orders in comes from the record too (A1005: 1 = one 4-pack). */\n    if(authoritative){ if(m.uom != null && m.uom !== \"\") p.uom = m.uom; if(m.case_qty != null) p.case_qty = Number(m.case_qty); }\n    /* MSRP / MAP basis (Phase 4): the record's word on an authoritative line; an empty basis leaves\n       the storefront's own rule in place (see msrpIsEach / mapIsEach). */\n    if(authoritative){ if(m.msrp_basis === \"each\" || m.msrp_basis === \"order_unit\") p.msrp_basis = m.msrp_basis;\n                       if(m.map_basis === \"each\" || m.map_basis === \"order_unit\") p.map_basis = m.map_basis; }\n    if(m.msrp_auto === false && m.msrp == null && p.msrp != null && p.msrp !== \"\"){\n      diffs.push({ code: p.code, field: \"msrp\", layers: p.msrp, record: null });\n      if(authoritative){ p.msrp = null; p.msrp_auto = false; delete p._msrp_suggested; }\n    }\n    if(m.tiers != null){\n      if(ladder(p.tiers) !== ladder(m.tiers)){\n        diffs.push({ code: p.code, field: \"tiers\", layers: ladder(p.tiers), record: ladder(m.tiers) });\n        if(authoritative) p.tiers = m.tiers;\n      }\n    }\n  });\n  return { matched, unmatched, diffs };\n}\n\nasync function applyMasterPrices(slug, prods){\n  const settle = (source, reason, extra) => {\n    CATALOG_SOURCE[slug] = Object.assign(\n      { source, reason, products: prods.length, at: new Date().toISOString() }, extra || {});\n    return prods;\n  };\n  try{\n    /* Two ways to be entitled to a price: a signed-in dealer, or staff viewing\n       as one. Preview deliberately never mints a dealer session, so it has no\n       JWT to send \u2014 and preview is how this storefront actually gets reviewed.\n       Leaving it on the old path would mean the view used to check the shop is\n       the one view that never exercises the new one. */\n    /* AUTH is a top-level `const` in this script, and a `const` is never a\n       property of window \u2014 so `window.AUTH` was always undefined, every load\n       settled on \"no dealer session\", and the feed was never fetched at all.\n       Read the binding itself. typeof guards the page states before it exists. */\n    const tok = (typeof AUTH !== 'undefined' && AUTH && AUTH.session && AUTH.session.access_token) || '';\n    const pv  = (typeof PREVIEW !== 'undefined' && PREVIEW && PREVIEW.token) ? PREVIEW.token : '';\n    if(!tok && !pv) return settle('layers', 'no dealer session or preview to authorise the feed');\n\n    let feed;\n    try{\n      const headers = tok ? { authorization: 'Bearer ' + tok } : { 'x-hcps-preview': pv };\n      const r = await fetch('/.netlify/functions/catalog-feed?manufacturer=' + encodeURIComponent(slug),\n                            { headers });\n      if(!r.ok) return settle('layers', 'feed returned HTTP ' + r.status);\n      feed = await r.json();\n    }catch(err){ return settle('layers', 'feed unreachable: ' + ((err && err.message) || err)); }\n\n    if(!feed || feed.migrated !== true)\n      return settle('layers', 'this line has not been migrated to the master record yet');\n\n    const rows = Array.isArray(feed.skus) ? feed.skus : [];\n    /* A migrated line answering with nothing is far more likely to be a fault\n       than a manufacturer with no sellable products. Treated as a fault. */\n    if(!rows.length)\n      return settle('layers', 'migrated line answered with no sellable SKUs \u2014 treated as a fault');\n\n    /* The line's own answer, and the global switch can only ever take it away.\n       A feed that has not been redeployed yet simply omits the field, which\n       reads as false \u2014 an old feed keeps the old behaviour rather than silently\n       handing authority to a record nobody checked. */\n    const authoritative = MASTER_PRICES_ENABLED === true && feed.authoritative === true;\n\n    const r = reconcileShopPrices(prods, rows, authoritative);\n    if(r.diffs.length) try{\n      console.warn('[HCPS] ' + slug + ': ' + r.diffs.length +\n        ' price difference(s) between the layers and the master record. ' +\n        (authoritative ? 'The record was used.' : 'The layers were used; run the reconciler.'),\n        r.diffs.slice(0, 20));\n    }catch(e){}\n\n    return settle(authoritative ? 'record' : 'layers',\n      authoritative ? 'master record is authoritative for this line'\n                    : ('compared against the master record; layers stand \u2014 ' +\n                       (feed.authority_note || 'this line still prices from the legacy layers')),\n      { compared: true, authoritative, matched: r.matched, unmatched: r.unmatched,\n        differences: r.diffs.length, diffs: r.diffs.slice(0, 50),\n        feed_generated_at: feed.generated_at, superseded: (feed.superseded || []).length });\n  }catch(err){\n    return settle('layers', 'price comparison failed: ' + ((err && err.message) || err));\n  }\n}\n\nconst COLOR_SUFFIX=/(BLUE|RED|GREY|GRAY|BLACK|WHITE|PINK|TAN|NAVY|GREEN|PURPLE|ORANGE|BEIGE|BK|WH|PK|DB|BL|GY|RD|NV|TN)$/;\nfunction inheritColorPrice(p){\n  const cur=Number(p.base_price);\n  const havePrice = p.base_price!=null && p.base_price!=='' && isFinite(cur) && cur>0;\n  const haveTiers = Array.isArray(p.tiers) && p.tiers.length>0;\n  if(havePrice && haveTiers) return p;\n  const idx=p._priceIndex; if(!idx) return p;\n  const tdx=p._tierIndex||{};\n  let code=String(p.code||'').toUpperCase();\n  const m=code.match(COLOR_SUFFIX); if(!m) return p;\n  for(const stem of [code.slice(0,m.index), code.slice(0,m.index).replace(/[-_\\s]+$/,'')]){\n    if(!stem || stem===code) continue;\n    const v=idx[stem];\n    if(v==null) continue;\n    if(!havePrice){ p.base_price=v; p._priceFromBase=stem; }\n    const rungs=tdx[stem];\n    const samePrice=Math.abs(Number(p.base_price)-Number(v))<0.005;\n    if(!haveTiers && samePrice && Array.isArray(rungs) && rungs.length){\n      p.tiers=rungs.map(t=>Object.assign({},t));\n      p._tiersFromBase=stem;\n    }\n    break;\n  }\n  return p;\n}\nfunction fillMsrp(p){\n  const base=Number(p.base_price);\n  if(p.msrp_auto===false) return p;     // MSRP deliberately absent \u2014 never fabricated (agreed 2026-10-09)\n  if((p.msrp==null||p.msrp===\"\") && base>0){ p.msrp=Math.round(base*2*100)/100; p._msrp_suggested=true; }\n  return p;\n}\n\n" };
